"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisHowItWorksContent } from "./components/how-it-works/content";
import View0 from "./components/how-it-works/variants/01-centered-cards";
const variants = {"centered-cards":View0};
export type { ArtemisHowItWorksContent, ArtemisHowItWorksLink, ArtemisHowItWorksStep } from "./components/how-it-works/content";
export interface ArtemisHowItWorksProps { className?: string; variant?: "centered-cards"; /** The words on the how-it-works section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHowItWorksContent>; }
export function ArtemisHowItWorks({ className, variant = "centered-cards", content }: ArtemisHowItWorksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisHowItWorksLink {
  label: string;
  href: string;
}

/** One step of the process. Layouts number the steps in order and draw their own scene for each one. */
export interface ArtemisHowItWorksStep {
  /** A short label over the title, such as "Collect". All layouts. Keep labels unique, since story-stack and card-deck tell steps apart by it. */
  label: string;
  /** The step's title. All layouts. */
  title: string;
  /** A sentence or two under the title. All layouts; card-deck shows two lines of it. */
  description: string;
  /** The step's icon. centered-cards, process-grid, walkthrough and card-deck, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis how-it-works section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHowItWorksContent {
  /** The small pill over the headline. All layouts. */
  badge: string;
  /** The heading. All layouts; process-grid, story-stack, walkthrough and card-deck break it into two lines at the middle word. */
  headline: string;
  /** A line or two beside or under the headline. All layouts. */
  subhead: string;
  /** The button after the steps or beside the subhead. centered-cards, process-grid, story-stack and walkthrough. */
  cta?: ArtemisHowItWorksLink;
  /** The steps, in order. All layouts; three look best, and card-deck's own list has four. */
  steps: ArtemisHowItWorksStep[];
}

"use client";
// @zeus-internal
import { ArrowRight, Rocket, ScanSearch } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import type { ComponentType } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisHowItWorksContent, ArtemisHowItWorksStep } from "../content";
import { UsersRound } from "./01-centered-cards/icons";
import { BriefScene, CaptureScene, LaunchScene } from "./01-centered-cards/scenes";
import { WordReveal } from "./01-centered-cards/word-reveal";
const INSTANT = { duration: 0 } as const;
const defaultSteps: ArtemisHowItWorksStep[] = [
    {
        label: "Understand",
        title: "Listen before shaping the answer",
        description: "Collect the request, its context, and the examples that reveal what a useful outcome should actually feel like.",
    },
    {
        label: "Align",
        title: "Make one direction easy to follow",
        description: "Turn the signal into a focused brief with clear decisions, an owner, and the next move everyone can see.",
    },
    {
        label: "Deliver",
        title: "Close the loop with confidence",
        description: "Review the finished work against the original intent, publish it, and keep the result visible after launch.",
    },
];
const DEFAULT = {
    badge: "How it works",
    headline: "Three steps. One clear outcome.",
    subhead: "A considered process keeps the original context connected to every decision, from the first request to the finished release.",
    cta: { label: "Explore the process", href: "#" },
    steps: defaultSteps,
} satisfies ArtemisHowItWorksContent;
/** The icon and scene for each slot, in turn; a step without an icon keeps its slot's. */
const ICONS = [ScanSearch, UsersRound, Rocket];
const SCENES = [<CaptureScene />, <BriefScene />, <LaunchScene />];
const HEADER_VIEWPORT = { once: true, margin: "-50px" } as const;
const CARD_VIEWPORT = { once: true, margin: "-70px" } as const;
const CTA_VIEWPORT = { once: true, margin: "-40px" } as const;
export default function HowItWorksCenteredCards({ content }: { content?: Partial<ArtemisHowItWorksContent> } = {}) {
    const reduce = useReducedMotion();
    const copy = { ...DEFAULT, ...content };
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div className="art:mx-auto art:max-w-3xl art:text-center">
          <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={{ opacity: 0, filter: "blur(5px)", transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={HEADER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
            {copy.badge}
          </motion.span>
          <WordReveal text={copy.headline} className="art:block art:mt-7 art:text-balance art:tracking-[-0.05em] art:text-4xl art:font-medium"/>
          <motion.p className="art:mx-auto art:mt-6 art:max-w-2xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7" initial={{ opacity: 0, filter: "blur(5px)", transform: "translate3d(0,10px,0)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={HEADER_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.5, delay: 0.28, ease: ARTEMIS_EASE_OUT }}>
            {copy.subhead}
          </motion.p>
        </div>
        <div className="art:mt-14 art:grid art:gap-4 art:@min-[640px]/artemis:mt-16 art:@min-[768px]/artemis:grid-cols-3 art:@min-[1024px]/artemis:gap-6">
          {copy.steps.map(({ icon, label, title, description }, i) => {
            const number = String(i + 1).padStart(2, "0");
            const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = icon ?? ICONS[i % ICONS.length];
            return (<motion.article key={number} className="art:min-w-0 art:rounded-3xl art:border art:border-border/70 art:bg-background art:p-3" initial={{ opacity: 0, filter: "blur(8px)", transform: "translate3d(0,18px,0)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={CARD_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.62, delay: i * 0.08, ease: ARTEMIS_EASE_OUT }}>
              <div className="art:relative art:h-48 art:overflow-hidden art:rounded-2xl art:bg-[radial-gradient(circle_at_50%_0%,color-mix(in_oklab,var(--artemis-primary)_12%,transparent),transparent_68%)] art:@min-[640px]/artemis:h-52">
                <div aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center">
                  {SCENES[i % SCENES.length]}
                </div>
              </div>
              <div className="art:p-4 art:pb-5 art:@min-[640px]/artemis:p-5 art:@min-[640px]/artemis:pb-6">
                <div className="art:flex art:items-center art:justify-between art:gap-4">
                  <span className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">Step {number}</span>
                  <span className="art:flex art:size-9 art:items-center art:justify-center art:bg-muted art:text-muted-foreground art:rounded-full">
                    <Icon className="art:size-4" strokeWidth={1.7}/>
                  </span>
                </div>
                <p className="art:mt-6 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{label}</p>
                <h3 className="art:mt-2 art:text-pretty art:font-medium art:text-xl art:leading-tight art:tracking-[-0.03em]">{title}</h3>
                <p className="art:mt-3 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{description}</p>
              </div>
            </motion.article>);
        })}
        </div>
        <motion.div className="art:mt-10 art:flex art:justify-center art:@min-[640px]/artemis:mt-12" initial={{ opacity: 0, transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={CTA_VIEWPORT} transition={reduce ? INSTANT : { duration: 0.45, delay: 0.22, ease: ARTEMIS_EASE_OUT }}>
          <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-card art:text-foreground art:hover:border-border art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0} whileHover={{ scale: 1.01 }} whileTap={{ scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS}>
            {copy.cta.label}
            <ArrowRight className="art:size-4"/>
          </motion.a>
        </motion.div>
      </div>
    </section>);
}

