"use client";
// @zeus-internal
import { Check, ClipboardCheck, FileText, type LucideIcon, MessageSquareText, Rocket } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const INSTANT = { duration: 0 } as const;
const VIEWPORT = { once: true, margin: "-40px" } as const;
const NOTES: ReadonlyArray<{
    icon: LucideIcon;
    label: string;
    from: string;
}> = [
    { icon: MessageSquareText, label: "Customer note", from: "translate3d(-34px,0,0)" },
    { icon: FileText, label: "Original brief", from: "translate3d(34px,0,0)" },
];
export function CaptureScene() {
    const reduce = useReducedMotion();
    return (<div className="art:w-[78%] art:space-y-2">
      {NOTES.map(({ icon: Icon, label, from }, i) => (<motion.div key={label} className="art:flex art:items-center art:gap-3 art:rounded-xl art:border art:border-border/70 art:bg-background/75 art:px-3 art:py-2.5 art:backdrop-blur-md" initial={{ opacity: 0, filter: "blur(5px)", transform: from }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={VIEWPORT} transition={reduce ? INSTANT : { duration: 0.52, delay: i * 0.07, ease: ARTEMIS_EASE_OUT }}>
          <span className="art:flex art:size-8 art:items-center art:justify-center art:bg-muted art:text-muted-foreground art:rounded-full">
            <Icon className="art:size-3.5"/>
          </span>
          <span className="art:font-medium art:text-xs">{label}</span>
        </motion.div>))}
    </div>);
}
const BRIEF_ITEMS = ["Outcome", "Owner", "Next move"] as const;
export function BriefScene() {
    const reduce = useReducedMotion();
    return (<div className="art:w-[78%] art:rounded-2xl art:border art:border-border/70 art:bg-background/75 art:p-3 art:backdrop-blur-md">
      <div className="art:mb-3 art:flex art:items-center art:justify-between">
        <span className="art:font-medium art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.14em]">Shared brief</span>
        <ClipboardCheck className="art:size-3.5 art:text-muted-foreground"/>
      </div>
      <div className="art:space-y-1.5">
        {BRIEF_ITEMS.map((item, i) => (<motion.div key={item} className="art:flex art:items-center art:gap-2 art:rounded-lg art:bg-muted/65 art:px-2.5 art:py-2" initial={{ opacity: 0, transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={VIEWPORT} transition={reduce ? INSTANT : { duration: 0.42, delay: i * 0.07, ease: ARTEMIS_EASE_OUT }}>
            <Check className="art:size-3 art:text-muted-foreground"/>
            <span className="art:font-medium art:text-xs">{item}</span>
          </motion.div>))}
      </div>
    </div>);
}
export function LaunchScene() {
    const reduce = useReducedMotion();
    return (<motion.div className="art:relative art:flex art:size-28 art:items-center art:justify-center art:rounded-3xl art:border art:border-border/70 art:bg-background/75 art:backdrop-blur-md" initial={{ opacity: 0, filter: "blur(7px)", transform: "scale(0.9)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "scale(1)" }} viewport={VIEWPORT} transition={reduce ? INSTANT : { duration: 0.58, ease: ARTEMIS_EASE_OUT }}>
      <span className="art:flex art:size-12 art:items-center art:justify-center art:bg-muted art:text-foreground art:rounded-full">
        <Rocket className="art:size-5"/>
      </span>
      <motion.span className="art:absolute art:-right-2 art:-bottom-2 art:flex art:size-9 art:items-center art:justify-center art:border art:border-border art:bg-background art:text-foreground art:rounded-full" initial={{ opacity: 0, transform: "translate3d(-6px,-6px,0) scale(0.8)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0) scale(1)" }} viewport={VIEWPORT} transition={reduce ? INSTANT : { duration: 0.45, delay: 0.18, ease: ARTEMIS_EASE_OUT }}>
        <Check className="art:size-4"/>
      </motion.span>
    </motion.div>);
}

"use client";
// @zeus-internal
import { ArtemisWordEntrance } from "../../../../lib/word-entrance";
export function WordReveal({ text, className }: { text: string; className: string }) {
  return <h2 className={className}><ArtemisWordEntrance words={text.split(" ")} stagger={0.06} yOffset="24%"/></h2>;
}

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";
import { artemisWordMotion, type ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisWordEntranceProps {
  words: string[];
  className?: string;
  stagger?: number;
  delay?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: ArtemisWordMotionOptions["spring"];
  once?: boolean;
  amount?: number;
  entered?: boolean;
}
export function ArtemisWordEntrance({
  words,
  className = "",
  stagger = 0.055,
  delay = 0,
  blur = 10,
  yOffset = "20%",
  amount = 0.4,
  spring,
  once = true,
  entered: externalEntry,
}: ArtemisWordEntranceProps) {
  const element = useRef<HTMLSpanElement>(null);
  const observed = useInView(element, { once, amount });
  const entered = externalEntry ?? observed;
  const reduced = useReducedMotion() === true;
  return (
    <span ref={element} className={`art:block ${className}`}>
      <span className="art:block">
        {words.map((word, index) => {
          const movement = artemisWordMotion(index, reduced, {
            delay,
            stagger,
            blur,
            yOffset,
            spring,
          });
          return (
            <motion.span
              key={index}
              className="art:inline-block"
              initial={movement.initial}
              // With reduced motion the words land on mount instead of waiting to be seen.
              animate={entered || reduced ? movement.animate : undefined}
              transition={movement.transition}
            >
              {word}
              {index < words.length - 1 && (
                <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                  {"\u00a0"}
                </span>
              )}
            </motion.span>
          );
        })}
      </span>
    </span>
  );
}

// @zeus-internal
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisWordMotionOptions {
  delay?: number;
  stagger?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: { stiffness?: number; damping?: number; mass?: number };
}
export function artemisWordMotion(
  index: number,
  reduced: boolean,
  { delay = 0, stagger = 0.055, blur = 10, yOffset = "20%", spring }: ArtemisWordMotionOptions = {}
) {
  const offset = delay + index * stagger;
  // The same start with reduced motion, so hydration matches the server; the words then land at once.
  return {
    initial: { opacity: 0, filter: `blur(${blur}px)`, y: yOffset },
    animate: { opacity: 1, filter: "blur(0px)", y: 0 },
    transition: reduced
      ? { duration: 0 }
      : {
          opacity: { duration: 0.7, delay: offset, ease: ARTEMIS_EASE_OUT },
          filter: { duration: 0.9, delay: offset, ease: ARTEMIS_EASE_OUT },
          y: {
            type: "spring" as const,
            stiffness: spring?.stiffness ?? 140,
            damping: spring?.damping ?? 26,
            mass: spring?.mass ?? 1.2,
            delay: offset,
          },
        },
  };
}
